window.EXERCISES = [{"id": 17, "chapter": 3, "title": "PROPIEDADES DE LAS SUSTANCIAS IÓNICAS, COVALENTES Y METÁLICAS", "subtitle": "En función de la información disponible para las sustancias A, B, C y D que se describen en el la tabla, responde:\n¿Cuál de estas sustancias es iónica? ¿Cuál metálica? ¿Cuál covalente?", "instructions": "Para cada sustancia selecciona la única respuesta correcta", "type": "quiz", "images": ["ej cap 3 17 PropCompuestos.jpg"], "data": {"questions": [{"type": "multichoice", "text": "A es una sustancia", "answers": [{"text": "Iónica", "correct": false, "feedback": "Intento incorrecto"}, {"text": "Covalente", "correct": false, "feedback": "Intento incorrecto"}, {"text": "Metálica", "correct": true, "feedback": "¡Correcto!"}]}, {"type": "multichoice", "text": "B es una sustancia", "answers": [{"text": "Iónica", "correct": false, "feedback": "Intento incorrecto"}, {"text": "Covalente", "correct": true, "feedback": "¡Correcto!"}, {"text": "Metálica", "correct": false, "feedback": "Intento incorrecto"}]}, {"type": "multichoice", "text": "C es una sustancia", "answers": [{"text": "Iónica", "correct": false, "feedback": "Intento incorrecto"}, {"text": "Covalente", "correct": true, "feedback": "¡Correcto!"}, {"text": "Metálica", "correct": false, "feedback": "Intento incorrecto"}]}, {"type": "multichoice", "text": "D es una sustancia", "answers": [{"text": "Iónica", "correct": true, "feedback": "¡Correcto!"}, {"text": "Covalente", "correct": false, "feedback": "Intento incorrecto"}, {"text": "Metálica", "correct": false, "feedback": "Intento incorrecto"}]}]}}, {"id": 18, "chapter": 3, "title": "COMPUESTOS IÓNICOS, COVALENTES y METÁLICOS", "subtitle": "Para cada una de las siguientes propiedades indica si corresponden a compuestos iónicos, metálicos o covalentes.", "instructions": "Despliega las opciones y elige la correcta", "type": "match", "images": [], "data": {"items": [{"left": "a) Conducen la corriente eléctrica sólo cuando están fundidos o disueltos.", "correct": ["COMPUESTOS IÓNICOS"]}, {"left": "b) Son buenos conductores del calor y la electricidad.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "c) Presentan uniones en las que los núcleos de los átomos quedan envueltos en una nube de electrones.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "d) Tiene bajos puntos de fusión y de ebullición.", "correct": ["COMPUESTOS COVALENTES"]}, {"left": "e) Son dúctiles y maleables.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "f) Presentan uniones en las que se forma un anión y un catión.", "correct": ["COMPUESTOS IÓNICOS"]}, {"left": "g) Son malos conductores del calor y la electricidad.", "correct": ["COMPUESTOS COVALENTES"]}, {"left": "h) Presentan uniones en las que comparten electrones de a pares.", "correct": ["COMPUESTOS COVALENTES"]}], "options": ["COMPUESTOS METÁLICOS", "COMPUESTOS COVALENTES", "COMPUESTOS IÓNICOS"]}}, {"id": 19, "chapter": 3, "title": "LA MOLÉCULA DE OZONO", "subtitle": "La anterior es una representación simbólica de una molécula de ozono. Luego de considerar la imagen, contesta las preguntas:", "instructions": "", "type": "quiz", "images": ["ozono.jpg"], "data": {"questions": [{"type": "short", "text": "¿Átomos de qué elementos están asociados?", "answers": [{"text": "oxígeno", "correct": true, "feedback": ""}]}, {"type": "short", "text": "¿Cuántos átomos hay?", "answers": [{"text": "3", "correct": true, "feedback": ""}, {"text": "tres", "correct": true, "feedback": ""}]}, {"type": "short", "text": "¿Cuál sería la fórmula de este compuesto?", "answers": [{"text": "O3", "correct": true, "feedback": ""}]}, {"type": "short", "text": "¿Qué representan los puntitos negros que se ven en la figura?", "answers": [{"text": "electrones del último nivel", "correct": true, "feedback": ""}]}, {"type": "short", "text": "¿Cómo se clasifica la asociación entre estos átomos: unión iónica, metálica o covalente?", "answers": [{"text": "covalente", "correct": true, "feedback": ""}]}]}}, {"id": 20, "chapter": 4, "title": "TIPOS DE COMPUESTOS QUÍMICOS", "subtitle": "Ejercicio de opción múltiple", "instructions": "Para cada compuesto químico selecciona la única opción que sea correcta", "type": "quiz", "images": [], "data": {"questions": [{"type": "multiselect", "text": "KOH", "answers": [{"text": "Óxido", "correct": false, "feedback": "No, es una base"}, {"text": "Ácido", "correct": false, "feedback": "No, es una base"}, {"text": "Base", "correct": true, "feedback": "Es una base"}, {"text": "Sal", "correct": false, "feedback": "No, es una base"}]}, {"type": "multiselect", "text": "SO₂", "answers": [{"text": "Óxido", "correct": true, "feedback": "Es un óxido"}, {"text": "Ácido", "correct": false, "feedback": "No, es Óxido"}, {"text": "Base", "correct": false, "feedback": "No, es Óxido"}, {"text": "Sal", "correct": false, "feedback": "No, es Óxido"}]}, {"type": "multiselect", "text": "CaO", "answers": [{"text": "Óxido", "correct": true, "feedback": "Es óxido"}, {"text": "Ácido", "correct": false, "feedback": "No, es un óxido"}, {"text": "Base", "correct": false, "feedback": "No, es un óxido"}, {"text": "Sal", "correct": false, "feedback": "No, es un óxido"}]}, {"type": "multiselect", "text": "H₂SO₄", "answers": [{"text": "Óxido", "correct": false, "feedback": "No, es un ácido"}, {"text": "Ácido", "correct": true, "feedback": "Es un ácido"}, {"text": "Base", "correct": false, "feedback": "No, es un ácido"}, {"text": "Sal", "correct": false, "feedback": "No, es un ácido"}]}, {"type": "multiselect", "text": "PbO", "answers": [{"text": "Óxido", "correct": true, "feedback": "Es un óxido"}, {"text": "Ácido", "correct": false, "feedback": "No, es un óxido"}, {"text": "Base", "correct": false, "feedback": "No, es un óxido"}, {"text": "Sal", "correct": false, "feedback": "No, es un óxido"}]}, {"type": "multiselect", "text": "NaCl", "answers": [{"text": "Óxido", "correct": false, "feedback": "No, es una sal"}, {"text": "Ácido", "correct": false, "feedback": "No, es una sal"}, {"text": "Base", "correct": false, "feedback": "No, es una sal"}, {"text": "Sal", "correct": true, "feedback": "Es una sal"}]}, {"type": "multiselect", "text": "Sr(OH)2", "answers": [{"text": "Óxido", "correct": false, "feedback": "No, es una base"}, {"text": "Ácido", "correct": false, "feedback": "No, es una base"}, {"text": "Base", "correct": true, "feedback": "Es una base"}, {"text": "Sal", "correct": false, "feedback": "No, es una base"}]}, {"type": "multiselect", "text": "CO", "answers": [{"text": "Óxido", "correct": true, "feedback": "Es un óxido"}, {"text": "Ácido", "correct": false, "feedback": "No, es un óxido"}, {"text": "Base", "correct": false, "feedback": "No, es un óxido"}, {"text": "Sal", "correct": false, "feedback": "No, es un óxido"}]}, {"type": "multiselect", "text": "NH3", "answers": [{"text": "Óxido", "correct": false, "feedback": "Es una base"}, {"text": "Ácido", "correct": false, "feedback": "Es una base"}, {"text": "Base", "correct": true, "feedback": "Es una base"}, {"text": "Sal", "correct": false, "feedback": "Es una base"}]}, {"type": "multiselect", "text": "HBr", "answers": [{"text": "Óxido", "correct": false, "feedback": "No, es un ácido"}, {"text": "Ácido", "correct": true, "feedback": "Es un ácido"}, {"text": "Base", "correct": false, "feedback": "No, es un ácido"}, {"text": "Sal", "correct": false, "feedback": "No, es un ácido"}]}]}}, {"id": 21, "chapter": 4, "title": "ESCALA DE pH", "subtitle": "Determiná qué tipo de solución corresponde a los siguientes valores de pH", "instructions": "Desplegá el menú y seleccioná la respuesta correcta", "type": "match", "images": [], "data": {"items": [{"left": "- pH 4", "correct": ["Solución ácida"]}, {"left": "- pH 7,5", "correct": ["Solución básica"]}, {"left": "- pH 11", "correct": ["Solución básica"]}, {"left": "- pH 1,9", "correct": ["Solución ácida"]}, {"left": "- pH 7", "correct": ["Solución neutra"]}], "options": ["Solución básica", "Solución neutra", "Solución ácida"]}}, {"id": 22, "chapter": 4, "title": "INDICADORES ÁCIDO-BASE", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá las palabras que faltan en los espacios en blanco. Luego presioná \"Comprobar\" para revisar tus respuestas. El botón \"Pista\" te dará una letra de la palabra. Tené en cuenta que las pistas te harán perder puntaje.\nRecordá colocar las tildes donde corresponda, de otro modo la palabra será tomada como incorrecta.", "type": "cloze", "images": [], "data": {"text": "1- El papel tornasol rojo presenta color {{1}} frente a una solución neutra.\n\n2- El papel tornasol azul presenta color {{2}} frente a una solución neutra.", "gaps": [{"n": 1, "answers": ["rojo"], "hint": ""}, {"n": 2, "answers": ["azul"], "hint": ""}], "caseSensitive": false}}, {"id": 23, "chapter": 5, "title": "CLASIFICACIÓN DE REACCIONES QUÍMICAS", "subtitle": "Ejercicio de emparejamiento", "instructions": "Despliega las opciones de la derecha y elige la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "a) Los productos pueden reaccionar entre sí para regresar a su estado anterior.", "correct": ["REACCIONES REVERSIBLES"]}, {"left": "b) Consiste en la unión de dos o más sustancias sencillas para formar una más compleja.", "correct": ["REACCIONES DE SÍNTESIS"]}, {"left": "c) Reacciones que se realizan en un solo sentido. Los productos formados no pueden, bajo condiciones normales, reaccionar entre sí para retornar a su estado original.", "correct": ["REACCIONES IRREVERSIBLES"]}, {"left": "d) Reacciones que generan cambios de energía.", "correct": ["REACCIONES TERMOQUÍMICAS"]}, {"left": "e) Reacciones donde intervienen la acción de un ácido sobre una base, produciendo agua y sal.", "correct": ["REACCIONES DE NEUTRALIZACIÓN"]}, {"left": "f) Una sustancia compleja, se descompone en 2 o más sustancias sencillas.", "correct": ["REACCIONES DE DESCOMPOSICIÓN"]}], "options": ["REACCIONES DE SÍNTESIS", "REACCIONES DE NEUTRALIZACIÓN", "REACCIONES DE DESCOMPOSICIÓN", "REACCIONES REVERSIBLES", "REACCIONES IRREVERSIBLES", "REACCIONES TERMOQUÍMICAS"]}}, {"id": 24, "chapter": 5, "title": "REACTIVOS Y PRODUCTOS", "subtitle": "En las siguientes frases, que describen diferentes reacciones químicas, identificar cuáles son los reactivos y cuáles son los productos.", "instructions": "En los espacios en blanco completá con una R si se trata de un reactivo o una P si se trata de un producto.", "type": "cloze", "images": [], "data": {"text": "a) En la fotosíntesis el dióxido de carbono y el agua se combinan para formar glucosa y oxígeno.\n - Dióxido de carbono {{1}} \n - Agua {{2}} \n - Glucosa {{3}} \n - Oxígeno {{4}} \n\nb) El bicarbonato de sodio y el vinagre al mezclarse generan una sal.\n - Bicarbonato de sodio {{5}} \n - Vinagre {{6}} \n - Sal {{7}} \n\nc) Un clavo de hierro se oxida generando óxido de hierro.\n - Hierro {{8}} \n - Oxígeno {{9}} \n - Óxido de hierro {{10}} \n\nd) Las cenizas de papel son el resultado de quemar un papel.\n - Cenizas de papel {{11}} \n - Papel {{12}} \n\ne) La digestión es el proceso de transformación de los alimentos, previamente ingeridos, en sustancias más sencillas para ser absorbidos.\n - Alimentos {{13}} \n - Sustancias más sencillas {{14}}", "gaps": [{"n": 1, "answers": ["R", "r"], "hint": ""}, {"n": 2, "answers": ["R", "r"], "hint": ""}, {"n": 3, "answers": ["P", "p"], "hint": ""}, {"n": 4, "answers": ["P", "p"], "hint": ""}, {"n": 5, "answers": ["R", "r"], "hint": ""}, {"n": 6, "answers": ["R", "r"], "hint": ""}, {"n": 7, "answers": ["P", "p"], "hint": ""}, {"n": 8, "answers": ["R", "r"], "hint": ""}, {"n": 9, "answers": ["R", "r"], "hint": ""}, {"n": 10, "answers": ["P", "p"], "hint": ""}, {"n": 11, "answers": ["P", "p"], "hint": ""}, {"n": 12, "answers": ["R", "r"], "hint": ""}, {"n": 13, "answers": ["R", "r"], "hint": ""}, {"n": 14, "answers": ["P", "p"], "hint": ""}], "caseSensitive": false}}, {"id": 25, "chapter": 5, "title": "ÁTOMOS DE HIDRÓGENO Y OXÍGENO", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá en cada espacio en blanco el número de átomos que corresponda.", "type": "cloze", "images": [], "data": {"text": "1- En una molécula de H2SO4 hay {{1}} átomos de hidrógeno y {{2}} átomos de oxígeno.\n\n2- En una unidad fórmula de molécula de Ca(OH)2 hay {{3}} átomos de hidrógeno y {{4}} átomos de oxígeno.\n\n3- En una unidad fórmula de molécula de Mg(HCO3)2 hay {{5}} átomos de hidrógeno y {{6}} átomos de oxígeno.\n\n4- En una unidad fórmula de molécula de Al2(SO4)3 hay {{7}} átomos de aluminio, {{8}} átomos de azufre y {{9}} átomos de oxígeno.", "gaps": [{"n": 1, "answers": ["2"], "hint": ""}, {"n": 2, "answers": ["4"], "hint": ""}, {"n": 3, "answers": ["2"], "hint": ""}, {"n": 4, "answers": ["2"], "hint": ""}, {"n": 5, "answers": ["2"], "hint": ""}, {"n": 6, "answers": ["6"], "hint": ""}, {"n": 7, "answers": ["2"], "hint": ""}, {"n": 8, "answers": ["3"], "hint": ""}, {"n": 9, "answers": ["12"], "hint": ""}], "caseSensitive": false}}, {"id": 26, "chapter": 6, "title": "BIOMOLÉCULAS", "subtitle": "Palabras Cruzadas", "instructions": "Completá el crucigrama. Hacé click sobre uno de los número del crucigrama para que aparezcan las preguntas. Escribí la palabra y luego presioná \"Introducir Respuesta\".\nSi estás confundido, hacé click sobre \"Pista\" para que aparezca una de las letras de la palabra. Luego, hacé click sobre \"Comprobar\" para verificar tus respuestas.", "type": "cross", "images": [], "data": {"grid": [["", "T", "", "", "", "", "", "", "", "", "G", "L", "U", "C", "I", "D", "O", "S", ""], ["", "R", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "A", ""], ["B", "I", "O", "G", "E", "N", "E", "S", "I", "C", "O", "S", "", "", "", "", "", "C", ""], ["", "G", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "A", ""], ["E", "L", "A", "S", "T", "I", "N", "A", "", "", "", "", "", "", "", "", "", "R", ""], ["", "I", "", "", "", "", "", "", "", "", "", "", "Q", "", "", "", "", "O", ""], ["", "C", "", "", "", "", "", "", "", "", "", "", "U", "", "", "", "", "S", ""], ["H", "E", "M", "O", "G", "L", "O", "B", "I", "N", "A", "", "E", "N", "Z", "I", "M", "A", "S"], ["", "R", "", "", "", "", "", "", "", "", "", "", "R", "", "", "", "", "", ""], ["V", "I", "T", "A", "M", "I", "N", "A", "S", "", "", "", "A", "", "", "", "", "", ""], ["", "D", "", "", "", "", "", "", "", "", "", "", "T", "", "", "", "C", "", ""], ["C", "O", "L", "E", "S", "T", "E", "R", "O", "L", "", "L", "I", "P", "I", "D", "O", "S", ""], ["", "S", "", "", "", "", "", "", "", "", "", "", "N", "", "", "", "L", "", ""], ["", "", "", "", "", "P", "R", "O", "T", "E", "I", "N", "A", "S", "", "", "A", "", ""], ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "G", "", ""], ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "E", "", ""], ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "N", "", ""], ["", "", "", "", "", "", "", "", "", "", "", "", "G", "L", "U", "C", "O", "S", "A"]], "across": [{"n": 2, "clue": "Biomoléculas que contienen carbono, hidrógeno y oxígeno. Sustancias de alto valor energético que pueden formar polímeros.", "answer": "GLUCIDOS", "row": 0, "col": 10}, {"n": 4, "clue": "Elementos químicos que forman parte de los seres vivos.", "answer": "BIOGENESICOS", "row": 2, "col": 0}, {"n": 5, "clue": "Proteína que forma gran parte de las venas y arterias.", "answer": "ELASTINA", "row": 4, "col": 0}, {"n": 7, "clue": "Proteína de los glóbulos rojos de la sangre encargada de transportar oxígeno.", "answer": "HEMOGLOBINA", "row": 7, "col": 0}, {"n": 8, "clue": "Proteínas cuya función es aumentar la velocidad de las reacciones químicas de los organismos.", "answer": "ENZIMAS", "row": 7, "col": 12}, {"n": 9, "clue": "Conjunto de compuestos orgánicos diversos que, en cantidades mínimas, son indispensables para regular el funcionamiento del organismo.", "answer": "VITAMINAS", "row": 9, "col": 0}, {"n": 11, "clue": "Tipo de lípido imprescindible para la vida de las personas. Participa en la formación de sustancias importantes (ej vitamina D).", "answer": "COLESTEROL", "row": 11, "col": 0}, {"n": 12, "clue": "Tipo de biomolécula de la cual los triglicéridos son uno de los más frecuentes que se pueden enontrar en los seres vivos.", "answer": "LIPIDOS", "row": 11, "col": 11}, {"n": 13, "clue": "Biopolímeros que forman parte de los seres vivos. Están formados por átomos de carbono, hidrógeno, oxígeno, nitrógeno y azufre agrupados en unidades llamadas aminoácidos.", "answer": "PROTEINAS", "row": 13, "col": 5}, {"n": 14, "clue": "Monosacárido elaborado durante el proceso de fotosíntesis a partir de dióxido de carbono del aire y el agua, usando como fuente de energía la luz solar.", "answer": "GLUCOSA", "row": 17, "col": 12}], "down": [{"n": 1, "clue": "Lípidos que actúan como fuente de energía cuando las reservas de hidratos de carbono se acaban; aislantes de órganos y de tejidos; también las utiliza el organismo para disolver ciertas vitaminas como la vitamina A .", "answer": "TRIGLICERIDOS", "row": 0, "col": 1}, {"n": 3, "clue": "Disacárido utilizado para endulzar un té o para hacer postres.", "answer": "SACAROSA", "row": 0, "col": 17}, {"n": 6, "clue": "Proteína que forma gran parte de nuestras uñas, piel y pelo.", "answer": "QUERATINA", "row": 5, "col": 12}, {"n": 10, "clue": "Proteína principal de los cartílagos, ligamentos y tendones.", "answer": "COLAGENO", "row": 10, "col": 16}]}}, {"id": 27, "chapter": 6, "title": "COMPUESTOS ORGÁNICOS", "subtitle": "Indicar si las siguientes afirmaciones son verdaderas o falsas", "instructions": "Para cada frase selecciona VERDADERO o FALSO", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "Las sustancias orgánicas solo se pueden obtener a partir de organismos vivos.", "answers": [{"text": "VERDADERO", "correct": false, "feedback": "Incorrecto"}, {"text": "FALSO", "correct": true, "feedback": "Correcto"}]}, {"type": "multichoice", "text": "En todas las sustancias orgánicas encontramos siempre presente átomos del elemento carbono.", "answers": [{"text": "VERDADERO", "correct": true, "feedback": "Correcto"}, {"text": "FALSO", "correct": false, "feedback": "Incorrecto"}]}, {"type": "multichoice", "text": "El tipo de unión química que predomina en las sustancias orgánicas es la iónica.", "answers": [{"text": "VERDADERO", "correct": false, "feedback": "Incorrecto"}, {"text": "FALSO", "correct": true, "feedback": "Correcto"}]}, {"type": "multichoice", "text": "La propiedad particular del elemento carbono, que explica la existencia de gran cantidad de compuestos orgánicos, se llama concatenación.", "answers": [{"text": "VERDADERO", "correct": true, "feedback": "Correcto"}, {"text": "FALSO", "correct": false, "feedback": "Incorrecto"}]}, {"type": "multichoice", "text": "Los elementos biogenésicos son únicamente el carbono y el hidrógeno.", "answers": [{"text": "VERDADERO", "correct": false, "feedback": "Incorrecto"}, {"text": "FALSO", "correct": true, "feedback": "Correcto"}]}]}}, {"id": 28, "chapter": 6, "title": "MOLÉCULAS ORGÁNICAS", "subtitle": "Ejercicio de opción múltiple", "instructions": "Para cada frase selecciona la única respuesta correcta", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "Todos los compuestos orgánicos contienen...", "answers": [{"text": "Oxígeno", "correct": false, "feedback": "No es correcto"}, {"text": "Fósforo", "correct": false, "feedback": "No es correcto"}, {"text": "Carbono", "correct": true, "feedback": "Correcto"}, {"text": "Nitrógeno", "correct": false, "feedback": "No es correcto"}]}, {"type": "multichoice", "text": "Los elementos llamados biogenésicos son...", "answers": [{"text": "C, H, S, N", "correct": false, "feedback": "No es correcto"}, {"text": "C, H, O, N", "correct": true, "feedback": "Correcto"}, {"text": "C, O, H, P", "correct": false, "feedback": "No es correcto"}, {"text": "C, H, Cl, O", "correct": false, "feedback": "No es correcto"}]}, {"type": "multichoice", "text": "En los compuestos orgánicos predomina la unión...", "answers": [{"text": "metálica", "correct": false, "feedback": "No es correcto"}, {"text": "covalente", "correct": true, "feedback": "Correcto"}, {"text": "iónica", "correct": false, "feedback": "No es correcto"}]}, {"type": "multichoice", "text": "Las sustancias orgánicas son compuestos...", "answers": [{"text": "termoestables", "correct": false, "feedback": "No es correcto"}, {"text": "se descomponen con facilidad", "correct": true, "feedback": "Correcto"}, {"text": "solubles en agua", "correct": false, "feedback": "No es correcto"}]}]}}, {"id": 29, "chapter": 6, "title": "COMBUSTIÓN", "subtitle": "Indicá si las siguientes afirmaciones son VERDADERAS o FALSAS", "instructions": "Para cada frase selecciona la única respuesta correcta", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "En una reacción de combustión los reactivos arden en presencia de dióxido de carbono.", "answers": [{"text": "VERDADERO", "correct": false, "feedback": "Intento incorrecto"}, {"text": "FALSO", "correct": true, "feedback": "¡Correcto!"}]}, {"type": "multichoice", "text": "Cuando una reacción de combustión se produce con escasa disponibilidad de oxígeno se obtiene como producto carbón, agua y energía.", "answers": [{"text": "VERDADERO", "correct": true, "feedback": "¡Correcto!"}, {"text": "FALSO", "correct": false, "feedback": "Intento incorrecto"}]}, {"type": "multichoice", "text": "Una reacción de combustión es completa cuando se produce con abundante disponibilidad de oxígeno.", "answers": [{"text": "VERDADERO", "correct": true, "feedback": "¡Correcto!"}, {"text": "FALSO", "correct": false, "feedback": "Intento incorrecto"}]}, {"type": "multichoice", "text": "Los productos que se obtienen en una combustión completa son agua y carbón (C).", "answers": [{"text": "VERDADERO", "correct": false, "feedback": "Intento incorrecto"}, {"text": "FALSO", "correct": true, "feedback": "¡Correcto!"}]}]}}, {"id": 30, "chapter": 7, "title": "PRODUCTOS DE ORIGEN PETROQUÍMICO", "subtitle": "En la lista de materiales que se muestra a continuación indicá cuáles se obtienen del petróleo y cuáles no tienen origen petroquímico", "instructions": "Desplegá el menú y seleccioná la respuesta correcta", "type": "match", "images": [], "data": {"items": [{"left": "VIDRIO", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "SAL DE MESA", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "PAPEL", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "ACEITES COMESTIBLES", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "GAS NATURAL", "correct": ["SE OBTIENE DEL PETRÓLEO"]}, {"left": "PLÁSTICOS", "correct": ["SE OBTIENE DEL PETRÓLEO"]}, {"left": "NAFTA", "correct": ["SE OBTIENE DEL PETRÓLEO"]}, {"left": "ARENA", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "HARINA", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "MÁRMOL", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "ACEITES LUBRICANTES", "correct": ["SE OBTIENE DEL PETRÓLEO"]}, {"left": "MADERA", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}, {"left": "BARNIZ", "correct": ["SE OBTIENE DEL PETRÓLEO"]}, {"left": "ROCAS", "correct": ["NO SE OBTIENE DEL PETRÓLEO"]}], "options": ["NO SE OBTIENE DEL PETRÓLEO", "SE OBTIENE DEL PETRÓLEO"]}}, {"id": 31, "chapter": 7, "title": "COMBUSTIBLES FÓSILES", "subtitle": "Rellenar los espacios en blanco", "instructions": "Ubicá las palabras de la siguiente lista en los espacios en blanco. Luego presioná \"Comprobar respuesta\" para revisar tus respuestas. El botón \"Pista\" te dará una letra de la palabra. Tené en cuenta que las pistas te harán perder puntaje.\nRecordá colocar las tildes donde corresponda, de otro modo la palabra será tomada como incorrecta.", "type": "cloze", "images": [], "data": {"text": "El gas natural es un gas de aspecto {{1}} y su composición es 80 % {{2}}. Se formó hace {{3}} de años cuando una serie de {{4}} descompuestos quedaron sepultados bajo lodo y arena, en lo más profundo de antiguos lagos y {{5}}. En la medida que se acumulaba {{6}} , arena y sedimentos, se fueron formando capas de roca a gran {{7}} . La {{8}} causada por el peso sobre estas capas, más el calor de la Tierra, transformaron lentamente el material orgánico en {{9}} y en gas natural.\nEl petróleo crudo es un líquido aceitoso, inflamable, cuyo color varía de incoloro a {{10}} , su composición es un mezcla de {{11}} .\nEl carbón es un sólido de color negro cuya composición es {{12}} , hidrocarburos volátiles, azufre y {{13}} .", "gaps": [{"n": 1, "answers": ["incoloro"], "hint": ""}, {"n": 2, "answers": ["metano"], "hint": ""}, {"n": 3, "answers": ["millones"], "hint": ""}, {"n": 4, "answers": ["organismos", "seres vivos"], "hint": ""}, {"n": 5, "answers": ["océanos", "mares"], "hint": ""}, {"n": 6, "answers": ["lodo"], "hint": ""}, {"n": 7, "answers": ["profundidad"], "hint": ""}, {"n": 8, "answers": ["presión"], "hint": ""}, {"n": 9, "answers": ["petróleo crudo"], "hint": ""}, {"n": 10, "answers": ["negro"], "hint": ""}, {"n": 11, "answers": ["hidrocarburos"], "hint": ""}, {"n": 12, "answers": ["carbono"], "hint": ""}, {"n": 13, "answers": ["nitrógeno"], "hint": ""}], "caseSensitive": false, "wordList": ["carbono", "hidrocarburos", "incoloro", "lodo", "metano", "millones", "negro", "nitrógeno", "océanos", "organismos", "petróleo crudo", "presión", "profundidad"]}}, {"id": 201, "part": 2, "chapter": 3, "title": "PROPIEDADES DE LAS SUSTANCIAS IÓNICAS, COVALENTES Y METÁLICAS", "subtitle": "A partir de la información de la tabla sobre las sustancias P, Q, R, S y T, decidí cuál es iónica, cuál metálica y cuál covalente.", "instructions": "Para cada sustancia seleccioná la única respuesta correcta.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "P es una sustancia", "explain": "No conduce en estado sólido pero sí fundida, y se disuelve en agua: es iónica.", "answers": [{"text": "Iónica", "correct": true}, {"text": "Covalente", "correct": false}, {"text": "Metálica", "correct": false}]}, {"type": "multichoice", "text": "Q es una sustancia", "explain": "Es un gas formado por moléculas, con punto de ebullición muy bajo: covalente.", "answers": [{"text": "Covalente", "correct": true}, {"text": "Iónica", "correct": false}, {"text": "Metálica", "correct": false}]}, {"type": "multichoice", "text": "R es una sustancia", "explain": "Conduce siempre la electricidad, es brillante y se puede laminar y estirar: metálica.", "answers": [{"text": "Metálica", "correct": true}, {"text": "Iónica", "correct": false}, {"text": "Covalente", "correct": false}]}, {"type": "multichoice", "text": "S es una sustancia", "explain": "Forma cristales, es una sal y conduce disuelta en agua: iónica.", "answers": [{"text": "Iónica", "correct": true}, {"text": "Covalente", "correct": false}, {"text": "Metálica", "correct": false}]}, {"type": "multichoice", "text": "T es una sustancia", "explain": "Líquido que no conduce la electricidad y está formado por moléculas: covalente.", "answers": [{"text": "Covalente", "correct": true}, {"text": "Iónica", "correct": false}, {"text": "Metálica", "correct": false}]}]}, "table": {"head": ["Sustancia", "Estado a temperatura ambiente", "¿Conduce la electricidad?", "Otras observaciones"], "rows": [["P", "Sólido", "No conduce sólida; sí cuando se funde", "Se disuelve en agua; puntos de fusión elevados"], ["Q", "Gas", "No", "Está formada por moléculas; punto de ebullición muy bajo"], ["R", "Sólido", "Sí, siempre", "Brillante; se puede laminar y estirar en hilos"], ["S", "Sólido", "No conduce sólida; sí disuelta en agua", "Forma cristales; es una sal"], ["T", "Líquido", "No", "Está formada por moléculas; punto de ebullición bajo"]]}}, {"id": 202, "part": 2, "chapter": 3, "title": "COMPUESTOS IÓNICOS, COVALENTES Y METÁLICOS", "subtitle": "Ejercicio de emparejamiento", "instructions": "Desplegá las opciones de la derecha y elegí la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "a) Los átomos comparten electrones de a pares.", "correct": ["COMPUESTOS COVALENTES"]}, {"left": "b) Los cationes están sumergidos en una nube de electrones.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "c) Se forman por la unión de un metal con un no metal.", "correct": ["COMPUESTOS IÓNICOS"]}, {"left": "d) Forman redes cristalinas de cationes y aniones.", "correct": ["COMPUESTOS IÓNICOS"]}, {"left": "e) Se unen únicamente átomos de no metales.", "correct": ["COMPUESTOS COVALENTES"]}, {"left": "f) Son maleables y dúctiles.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "g) Conducen la electricidad cuando se funden o se disuelven en agua.", "correct": ["COMPUESTOS IÓNICOS"]}, {"left": "h) Salvo el mercurio, son sólidos a temperatura ambiente.", "correct": ["COMPUESTOS METÁLICOS"]}, {"left": "i) Forman moléculas; con átomos de carbono pueden formar macromoléculas.", "correct": ["COMPUESTOS COVALENTES"]}], "options": ["COMPUESTOS IÓNICOS", "COMPUESTOS COVALENTES", "COMPUESTOS METÁLICOS"]}}, {"id": 203, "part": 2, "chapter": 3, "title": "LA MOLÉCULA DE DIÓXIDO DE CARBONO", "subtitle": "El dióxido de carbono se representa O=C=O: el carbono comparte dos pares de electrones con cada átomo de oxígeno. Considerá esa información y contestá las preguntas.", "instructions": "Escribí la respuesta. Las tildes y las mayúsculas no cuentan.", "type": "quiz", "images": [], "data": {"questions": [{"type": "short", "text": "¿Cuántos átomos de oxígeno hay en la molécula?", "explain": "", "answers": [{"text": "2", "correct": true}, {"text": "dos", "correct": true}]}, {"type": "short", "text": "¿Cuántos átomos de carbono hay en la molécula?", "explain": "", "answers": [{"text": "1", "correct": true}, {"text": "uno", "correct": true}, {"text": "un", "correct": true}]}, {"type": "short", "text": "¿Cuál es la fórmula de este compuesto?", "explain": "Un carbono y dos oxígenos.", "answers": [{"text": "CO2", "correct": true}, {"text": "CO₂", "correct": true}]}, {"type": "short", "text": "¿Cuántos pares de electrones comparte el carbono con cada oxígeno?", "explain": "", "answers": [{"text": "2", "correct": true}, {"text": "dos", "correct": true}]}, {"type": "short", "text": "¿Cómo se llama el enlace en el que se comparten dos pares de electrones?", "explain": "", "answers": [{"text": "doble", "correct": true}, {"text": "enlace doble", "correct": true}, {"text": "doble enlace", "correct": true}, {"text": "union doble", "correct": true}]}, {"type": "short", "text": "¿Cuántos electrones queda rodeando cada átomo en su último nivel?", "explain": "Cumplen la regla del octeto.", "answers": [{"text": "8", "correct": true}, {"text": "ocho", "correct": true}]}, {"type": "short", "text": "¿Cómo se clasifica la unión entre estos átomos: iónica, metálica o covalente?", "explain": "Los dos son no metales y comparten electrones.", "answers": [{"text": "covalente", "correct": true}]}]}}, {"id": 204, "part": 2, "chapter": 3, "title": "UNIÓN IÓNICA Y UNIÓN COVALENTE", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá la palabra que falta en cada espacio. Las tildes y las mayúsculas no cuentan.", "type": "cloze", "images": [], "data": {"text": "1- En la unión iónica un átomo {{1}} electrones y el otro los {{2}}.\n\n2- El átomo metálico que cede electrones queda con carga positiva y se llama {{3}}; el átomo no metálico que los recibe se llama {{4}}.\n\n3- Los iones de carga opuesta se mantienen unidos por la atracción {{5}}.\n\n4- Las sustancias iónicas forman redes {{6}}, se disuelven en agua y conducen la electricidad cuando están fundidas o {{7}} en agua.\n\n5- En la unión covalente los átomos de los no metales {{8}} electrones de a pares y forman {{9}}.", "gaps": [{"n": 1, "answers": ["cede", "pierde"], "hint": ""}, {"n": 2, "answers": ["gana", "recibe", "capta", "incorpora"], "hint": ""}, {"n": 3, "answers": ["catión", "cation"], "hint": ""}, {"n": 4, "answers": ["anión", "anion"], "hint": ""}, {"n": 5, "answers": ["electrostática"], "hint": ""}, {"n": 6, "answers": ["cristalinas"], "hint": ""}, {"n": 7, "answers": ["disueltas", "disueltos", "disuelta", "en solución"], "hint": ""}, {"n": 8, "answers": ["comparten"], "hint": ""}, {"n": 9, "answers": ["moléculas"], "hint": ""}], "caseSensitive": false}}, {"id": 205, "part": 2, "chapter": 4, "title": "TIPOS DE COMPUESTOS QUÍMICOS", "subtitle": "", "instructions": "Para cada compuesto seleccioná la única opción correcta.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "HCl", "explain": "Tiene hidrógeno unido a un no metal.", "answers": [{"text": "Ácido", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "Mg(OH)₂", "explain": "Un metal unido a grupos oxhidrilo: hidróxido.", "answers": [{"text": "Base", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "SO₃", "explain": "Binario de oxígeno con un no metal.", "answers": [{"text": "Óxido", "correct": true}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "CaCO₃", "explain": "Metal unido a un grupo no metálico (carbonato).", "answers": [{"text": "Sal", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}]}, {"type": "multichoice", "text": "H₂SO₄", "explain": "Hidrógeno unido a un no metal acompañado de oxígeno.", "answers": [{"text": "Ácido", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "Na₂O", "explain": "Oxígeno unido a un metal.", "answers": [{"text": "Óxido", "correct": true}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "Al(OH)₃", "explain": "Hidróxido: metal + oxhidrilos.", "answers": [{"text": "Base", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "CuSO₄", "explain": "Metal (cobre) unido al grupo sulfato.", "answers": [{"text": "Sal", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}]}, {"type": "multichoice", "text": "H₃PO₄", "explain": "Hidrógeno + grupo no metálico con oxígeno.", "answers": [{"text": "Ácido", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "MgCl₂", "explain": "Metal unido a un no metal.", "answers": [{"text": "Sal", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}]}, {"type": "multichoice", "text": "Fe₂O₃", "explain": "Oxígeno + metal (hierro).", "answers": [{"text": "Óxido", "correct": true}, {"text": "Ácido", "correct": false}, {"text": "Base", "correct": false}, {"text": "Sal", "correct": false}]}, {"type": "multichoice", "text": "KOH", "explain": "Metal unido a un oxhidrilo.", "answers": [{"text": "Base", "correct": true}, {"text": "Óxido", "correct": false}, {"text": "Ácido", "correct": false}, {"text": "Sal", "correct": false}]}]}}, {"id": 206, "part": 2, "chapter": 4, "title": "ESCALA DE pH", "subtitle": "Determiná qué tipo de solución corresponde a los siguientes valores de pH", "instructions": "Desplegá el menú y seleccioná la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "- pH 3", "correct": ["Solución ácida"]}, {"left": "- pH 8,5", "correct": ["Solución básica"]}, {"left": "- pH 13", "correct": ["Solución básica"]}, {"left": "- pH 6,2", "correct": ["Solución ácida"]}, {"left": "- pH 7", "correct": ["Solución neutra"]}, {"left": "- pH 10", "correct": ["Solución básica"]}, {"left": "- pH 0,5", "correct": ["Solución ácida"]}], "options": ["Solución ácida", "Solución básica", "Solución neutra"]}}, {"id": 207, "part": 2, "chapter": 4, "title": "CONCEPTO DE pH", "subtitle": "", "instructions": "Seleccioná la única respuesta correcta.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "El pH es una medida de…", "explain": "", "shuffle": true, "answers": [{"text": "la acidez, con valores de 0 a 14", "correct": true}, {"text": "la temperatura de una solución", "correct": false}, {"text": "la cantidad de agua de una solución", "correct": false}, {"text": "la densidad de una solución, de 0 a 100", "correct": false}]}, {"type": "multichoice", "text": "Una sustancia neutra tiene un pH…", "explain": "Ácidas: menor que 7. Básicas: mayor que 7.", "shuffle": true, "answers": [{"text": "igual a 7", "correct": true}, {"text": "menor que 7", "correct": false}, {"text": "mayor que 7", "correct": false}, {"text": "igual a 0", "correct": false}]}, {"type": "multichoice", "text": "¿Cuál de estas soluciones es la más ácida?", "explain": "Cuanto menor el pH, más ácida.", "shuffle": true, "answers": [{"text": "pH 2", "correct": true}, {"text": "pH 5", "correct": false}, {"text": "pH 7", "correct": false}, {"text": "pH 12", "correct": false}]}, {"type": "multichoice", "text": "¿Cuál de estas soluciones es la menos básica?", "explain": "Todas son básicas; la más cercana a 7 es la menos básica.", "shuffle": true, "answers": [{"text": "pH 8", "correct": true}, {"text": "pH 9", "correct": false}, {"text": "pH 10,5", "correct": false}, {"text": "pH 13,5", "correct": false}]}, {"type": "multichoice", "text": "¿Cuál es el instrumento de laboratorio que mide el pH?", "explain": "", "shuffle": true, "answers": [{"text": "El pH-metro", "correct": true}, {"text": "El termómetro", "correct": false}, {"text": "La probeta", "correct": false}, {"text": "El tubo de ensayo", "correct": false}]}, {"type": "multichoice", "text": "¿Qué indica la notación pH ∈ (7, 14]?", "explain": "El paréntesis excluye el 7.", "shuffle": true, "answers": [{"text": "Una sustancia básica", "correct": true}, {"text": "Una sustancia ácida", "correct": false}, {"text": "Una sustancia neutra", "correct": false}, {"text": "Una sustancia que no tiene pH", "correct": false}]}, {"type": "multichoice", "text": "¿Entre qué valores se recomienda que esté el pH de un líquido para no dañar la piel?", "explain": "", "shuffle": true, "answers": [{"text": "Entre 4 y 9", "correct": true}, {"text": "Entre 0 y 2", "correct": false}, {"text": "Entre 10 y 14", "correct": false}, {"text": "Solo exactamente 7", "correct": false}]}]}}, {"id": 208, "part": 2, "chapter": 4, "title": "INDICADORES ÁCIDO-BASE", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá las palabras que faltan. Las tildes y las mayúsculas no cuentan.", "type": "cloze", "images": [], "data": {"text": "1- El papel tornasol azul se pone de color {{1}} frente a un ácido.\n\n2- El papel tornasol rojo se pone de color {{2}} frente a una base.\n\n3- La fenolftaleína es incolora en medio {{3}} y se pone de color rojo grosella en medio {{4}}.\n\n4- Las sustancias que cambian de color según el pH se llaman {{5}}.", "gaps": [{"n": 1, "answers": ["rojo"], "hint": ""}, {"n": 2, "answers": ["azul"], "hint": ""}, {"n": 3, "answers": ["ácido", "acido", "ácida"], "hint": ""}, {"n": 4, "answers": ["básico", "alcalino", "básica", "basico"], "hint": ""}, {"n": 5, "answers": ["indicadores"], "hint": ""}], "caseSensitive": false}}, {"id": 209, "part": 2, "chapter": 4, "title": "ÓXIDOS, ÁCIDOS, BASES Y SALES", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá la palabra que falta. Las tildes y las mayúsculas no cuentan.", "type": "cloze", "images": [], "data": {"text": "1- Los óxidos son sustancias {{1}} formadas por oxígeno y otro elemento.\n\n2- El carácter ácido lo da la presencia de {{2}}.\n\n3- Las bases o hidróxidos tienen un metal unido a uno o más grupos {{3}}.\n\n4- El NaCl se llama cloruro de {{4}}.\n\n5- Cuando un ácido y una base reaccionan se forman una sal y {{5}}.\n\n6- La lluvia ácida se forma cuando los óxidos de {{6}} y de nitrógeno reaccionan con el agua y el oxígeno de la atmósfera.\n\n7- El ácido del vinagre es el ácido {{7}} y el de las gaseosas es el ácido {{8}}.", "gaps": [{"n": 1, "answers": ["binarias", "binarios"], "hint": ""}, {"n": 2, "answers": ["hidrógeno", "hidrogeno"], "hint": ""}, {"n": 3, "answers": ["oxhidrilo", "hidroxilo", "OH", "oxidrilo"], "hint": ""}, {"n": 4, "answers": ["sodio"], "hint": ""}, {"n": 5, "answers": ["agua"], "hint": ""}, {"n": 6, "answers": ["azufre"], "hint": ""}, {"n": 7, "answers": ["acético"], "hint": ""}, {"n": 8, "answers": ["carbónico"], "hint": ""}], "caseSensitive": false}}, {"id": 210, "part": 2, "chapter": 5, "title": "CLASIFICACIÓN DE REACCIONES QUÍMICAS", "subtitle": "Ejercicio de emparejamiento", "instructions": "Desplegá las opciones de la derecha y elegí la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "a) Un ácido y una base reaccionan y se forman una sal y agua.", "correct": ["REACCIONES DE NEUTRALIZACIÓN"]}, {"left": "b) Varias sustancias sencillas se unen para formar una más compleja.", "correct": ["REACCIONES DE SÍNTESIS"]}, {"left": "c) Una sustancia compleja se transforma en dos o más sustancias más sencillas.", "correct": ["REACCIONES DE DESCOMPOSICIÓN"]}, {"left": "d) Absorben calor del ambiente.", "correct": ["REACCIONES ENDOTÉRMICAS"]}, {"left": "e) Liberan calor.", "correct": ["REACCIONES EXOTÉRMICAS"]}, {"left": "f) Transcurren en un solo sentido hasta que se consume el reactivo que está en defecto.", "correct": ["REACCIONES IRREVERSIBLES"]}, {"left": "g) Se representan con dos flechas de sentidos opuestos.", "correct": ["REACCIONES REVERSIBLES"]}, {"left": "h) Combustible + oxígeno → sustancia carbonada + agua + energía.", "correct": ["REACCIONES DE COMBUSTIÓN"]}], "options": ["REACCIONES DE SÍNTESIS", "REACCIONES DE DESCOMPOSICIÓN", "REACCIONES DE NEUTRALIZACIÓN", "REACCIONES DE COMBUSTIÓN", "REACCIONES ENDOTÉRMICAS", "REACCIONES EXOTÉRMICAS", "REACCIONES REVERSIBLES", "REACCIONES IRREVERSIBLES"]}}, {"id": 211, "part": 2, "chapter": 5, "title": "REACTIVOS Y PRODUCTOS", "subtitle": "En las siguientes frases, que describen diferentes reacciones químicas, identificá cuáles son los reactivos y cuáles son los productos.", "instructions": "En los espacios en blanco completá con una R si se trata de un reactivo o una P si se trata de un producto.", "type": "cloze", "images": [], "data": {"text": "a) En la combustión del metano, el metano y el oxígeno reaccionan y se forman dióxido de carbono, agua y energía.\n - Metano {{1}}\n - Oxígeno {{2}}\n - Dióxido de carbono {{3}}\n - Agua {{4}}\n\nb) Un antiácido con hidróxido de aluminio neutraliza el ácido clorhídrico del estómago y se forman cloruro de aluminio y agua.\n - Hidróxido de aluminio {{5}}\n - Ácido clorhídrico {{6}}\n - Cloruro de aluminio {{7}}\n - Agua {{8}}\n\nc) Al calentar el óxido de mercurio se descompone en mercurio y oxígeno.\n - Óxido de mercurio {{9}}\n - Mercurio {{10}}\n - Oxígeno {{11}}\n\nd) El hidrógeno y el yodo se combinan y forman yoduro de hidrógeno.\n - Hidrógeno {{12}}\n - Yodo {{13}}\n - Yoduro de hidrógeno {{14}}\n\ne) La picadura de una hormiga (ácido fórmico) se neutraliza con amoníaco y se obtienen una sal y agua.\n - Ácido fórmico {{15}}\n - Amoníaco {{16}}\n - Sal {{17}}\n - Agua {{18}}", "gaps": [{"n": 1, "answers": ["R", "r"], "hint": ""}, {"n": 2, "answers": ["R", "r"], "hint": ""}, {"n": 3, "answers": ["P", "p"], "hint": ""}, {"n": 4, "answers": ["P", "p"], "hint": ""}, {"n": 5, "answers": ["R", "r"], "hint": ""}, {"n": 6, "answers": ["R", "r"], "hint": ""}, {"n": 7, "answers": ["P", "p"], "hint": ""}, {"n": 8, "answers": ["P", "p"], "hint": ""}, {"n": 9, "answers": ["R", "r"], "hint": ""}, {"n": 10, "answers": ["P", "p"], "hint": ""}, {"n": 11, "answers": ["P", "p"], "hint": ""}, {"n": 12, "answers": ["R", "r"], "hint": ""}, {"n": 13, "answers": ["R", "r"], "hint": ""}, {"n": 14, "answers": ["P", "p"], "hint": ""}, {"n": 15, "answers": ["R", "r"], "hint": ""}, {"n": 16, "answers": ["R", "r"], "hint": ""}, {"n": 17, "answers": ["P", "p"], "hint": ""}, {"n": 18, "answers": ["P", "p"], "hint": ""}], "caseSensitive": false}}, {"id": 212, "part": 2, "chapter": 5, "title": "ÁTOMOS EN UNA FÓRMULA", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá en cada espacio el número de átomos que corresponda.", "type": "cloze", "images": [], "data": {"text": "1- En una molécula de HNO₃ hay {{1}} átomo de hidrógeno, {{2}} átomo de nitrógeno y {{3}} átomos de oxígeno.\n\n2- En una unidad fórmula de Al(OH)₃ hay {{4}} átomo de aluminio, {{5}} átomos de oxígeno y {{6}} átomos de hidrógeno.\n\n3- En una unidad fórmula de Ca(NO₃)₂ hay {{7}} átomo de calcio, {{8}} átomos de nitrógeno y {{9}} átomos de oxígeno.\n\n4- En una unidad fórmula de Fe₂(SO₄)₃ hay {{10}} átomos de hierro, {{11}} átomos de azufre y {{12}} átomos de oxígeno.\n\n5- En 3 moléculas de H₂O hay {{13}} átomos de hidrógeno y {{14}} átomos de oxígeno.\n\n6- En una unidad fórmula de NaHCO₃ hay {{15}} átomo de sodio, {{16}} átomo de hidrógeno, {{17}} átomo de carbono y {{18}} átomos de oxígeno.", "gaps": [{"n": 1, "answers": ["1"], "hint": ""}, {"n": 2, "answers": ["1"], "hint": ""}, {"n": 3, "answers": ["3"], "hint": ""}, {"n": 4, "answers": ["1"], "hint": ""}, {"n": 5, "answers": ["3"], "hint": ""}, {"n": 6, "answers": ["3"], "hint": ""}, {"n": 7, "answers": ["1"], "hint": ""}, {"n": 8, "answers": ["2"], "hint": ""}, {"n": 9, "answers": ["6"], "hint": ""}, {"n": 10, "answers": ["2"], "hint": ""}, {"n": 11, "answers": ["3"], "hint": ""}, {"n": 12, "answers": ["12"], "hint": ""}, {"n": 13, "answers": ["6"], "hint": ""}, {"n": 14, "answers": ["3"], "hint": ""}, {"n": 15, "answers": ["1"], "hint": ""}, {"n": 16, "answers": ["1"], "hint": ""}, {"n": 17, "answers": ["1"], "hint": ""}, {"n": 18, "answers": ["3"], "hint": ""}], "caseSensitive": false}}, {"id": 213, "part": 2, "chapter": 6, "title": "BIOMOLÉCULAS Y QUÍMICA DEL CARBONO", "subtitle": "Resolvé el crucigrama.", "instructions": "Escribí una letra por casillero, sin tildes.", "type": "cross", "images": [], "data": {"grid": [["", "", "G", "L", "U", "C", "O", "G", "E", "N", "O", "", ""], ["", "", "", "", "", "O", "", "", "", "", "", "", ""], ["", "", "", "", "I", "N", "S", "U", "L", "I", "N", "A", ""], ["", "", "", "", "", "C", "", "", "", "", "", "", ""], ["", "", "", "", "", "A", "", "", "", "", "", "", ""], ["", "", "", "", "", "T", "", "", "", "", "", "", ""], ["", "", "", "", "C", "E", "L", "U", "L", "O", "S", "A", ""], ["", "", "", "", "", "N", "", "", "", "", "", "L", ""], ["", "", "", "", "", "A", "", "", "", "N", "", "C", ""], ["H", "I", "D", "R", "O", "C", "A", "R", "B", "U", "R", "O", "S"], ["", "", "", "", "", "I", "", "", "", "C", "", "H", ""], ["A", "L", "M", "I", "D", "O", "N", "", "", "L", "", "O", ""], ["", "", "", "", "", "N", "", "", "", "E", "", "L", ""], ["", "", "", "", "", "", "", "", "", "O", "", "", ""], ["", "", "", "", "", "F", "R", "U", "C", "T", "O", "S", "A"], ["", "", "", "", "", "", "", "", "", "I", "", "", ""], ["", "A", "M", "I", "N", "O", "A", "C", "I", "D", "O", "S", ""], ["", "", "", "", "", "", "", "", "", "O", "", "", ""], ["", "P", "O", "L", "I", "M", "E", "R", "O", "S", "", "", ""]], "across": [{"n": 1, "clue": "Polisacárido de reserva de energía en las células animales.", "answer": "GLUCOGENO", "row": 0, "col": 2}, {"n": 3, "clue": "Proteína reguladora que controla el nivel de azúcar en la sangre.", "answer": "INSULINA", "row": 2, "col": 4}, {"n": 4, "clue": "Polisacárido que forma la pared celular de los vegetales.", "answer": "CELULOSA", "row": 6, "col": 4}, {"n": 7, "clue": "Compuestos que contienen sólo carbono e hidrógeno.", "answer": "HIDROCARBUROS", "row": 9, "col": 0}, {"n": 8, "clue": "Polisacárido de reserva de energía en los vegetales.", "answer": "ALMIDON", "row": 11, "col": 0}, {"n": 9, "clue": "Monosacárido presente en la miel y en las frutas.", "answer": "FRUCTOSA", "row": 14, "col": 5}, {"n": 10, "clue": "Monómeros que forman las proteínas.", "answer": "AMINOACIDOS", "row": 16, "col": 1}, {"n": 11, "clue": "Moléculas muy grandes formadas por la unión de muchas moléculas pequeñas, llamadas monómeros.", "answer": "POLIMEROS", "row": 18, "col": 1}], "down": [{"n": 2, "clue": "Capacidad del carbono de unirse a otros carbonos formando cadenas largas.", "answer": "CONCATENACION", "row": 0, "col": 5}, {"n": 5, "clue": "Función orgánica oxigenada cuyo grupo funcional es –OH.", "answer": "ALCOHOL", "row": 6, "col": 11}, {"n": 6, "clue": "Monómeros de los ácidos nucleicos.", "answer": "NUCLEOTIDOS", "row": 8, "col": 9}]}}, {"id": 214, "part": 2, "chapter": 6, "title": "COMPUESTOS ORGÁNICOS", "subtitle": "Indicar si las siguientes afirmaciones son verdaderas o falsas", "instructions": "Para cada frase seleccioná VERDADERO o FALSO.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "Los compuestos orgánicos contienen siempre carbono y, en casi todos los casos, hidrógeno.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Los carbonatos y los óxidos simples de carbono, como el CO₂, se consideran compuestos inorgánicos.", "explain": "La guía los clasifica como inorgánicos.", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "La mayoría de las sustancias orgánicas se disuelve muy bien en agua.", "explain": "La mayoría no tiene afinidad por el agua, sobre todo con más de cinco átomos de carbono.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "Las sustancias orgánicas conducen la electricidad igual que las iónicas.", "explain": "No conducen la electricidad.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "Al calentar azúcar queda un residuo de carbono porque las sustancias orgánicas se descomponen por el calor.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El vinagre y la madera son materiales orgánicos; la sal de mesa y el vidrio son inorgánicos.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Los hidrocarburos contienen carbono, hidrógeno y oxígeno.", "explain": "Contienen solo carbono e hidrógeno.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "Los compuestos con el mismo grupo funcional forman una función química y muestran propiedades parecidas.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Hasta principios del siglo XIX se creía que las sustancias orgánicas solo podían producirlas los seres vivos, por una 'fuerza vital'.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}]}}, {"id": 215, "part": 2, "chapter": 6, "title": "MOLÉCULAS ORGÁNICAS Y GRUPOS FUNCIONALES", "subtitle": "Ejercicio de opción múltiple", "instructions": "Para cada frase seleccioná la única respuesta correcta.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "El grupo funcional de los alcoholes es…", "explain": "–COOH: ácidos. –CHO: aldehídos. –CO–: cetonas.", "shuffle": true, "answers": [{"text": "–OH", "correct": true}, {"text": "–COOH", "correct": false}, {"text": "–CHO", "correct": false}, {"text": "–CO–", "correct": false}]}, {"type": "multichoice", "text": "El ácido acético del vinagre tiene el grupo funcional…", "explain": "–COO– es de los ésteres.", "shuffle": true, "answers": [{"text": "–COOH", "correct": true}, {"text": "–CHO", "correct": false}, {"text": "–COO–", "correct": false}, {"text": "–O–", "correct": false}]}, {"type": "multichoice", "text": "La propanona (acetona), el quitaesmalte, es un ejemplo de…", "explain": "", "shuffle": true, "answers": [{"text": "una cetona", "correct": true}, {"text": "un éter", "correct": false}, {"text": "un éster", "correct": false}, {"text": "un aldehído", "correct": false}]}, {"type": "multichoice", "text": "¿Qué función oxigenada da el aroma de frutas como la banana y la frutilla y se usa en perfumes y golosinas?", "explain": "Éster ≠ éter.", "shuffle": true, "answers": [{"text": "Los ésteres", "correct": true}, {"text": "Los éteres", "correct": false}, {"text": "Los aldehídos", "correct": false}, {"text": "Los alcoholes", "correct": false}]}, {"type": "multichoice", "text": "Si en el etano se reemplaza un hidrógeno por el grupo –OH se obtiene…", "explain": "El alcohol en gel es etanol.", "shuffle": true, "answers": [{"text": "etanol", "correct": true}, {"text": "etanal", "correct": false}, {"text": "metanol", "correct": false}, {"text": "ácido etanoico", "correct": false}]}, {"type": "multichoice", "text": "El metanal (formol) se usa para…", "explain": "", "shuffle": true, "answers": [{"text": "conservar muestras biológicas", "correct": true}, {"text": "quitar el esmalte de uñas", "correct": false}, {"text": "dar aroma a las frutas", "correct": false}, {"text": "preparar vinagre", "correct": false}]}, {"type": "multichoice", "text": "El éter etílico se usó como…", "explain": "", "shuffle": true, "answers": [{"text": "anestesia y solvente", "correct": true}, {"text": "conservante de alimentos", "correct": false}, {"text": "perfume de frutas", "correct": false}, {"text": "combustible de motores", "correct": false}]}, {"type": "multichoice", "text": "Los hidrocarburos que tienen solo enlaces simples entre carbonos se llaman…", "explain": "Alcanos: -ano. Alquenos: -eno (doble). Alquinos: -ino (triple).", "shuffle": true, "answers": [{"text": "alcanos", "correct": true}, {"text": "alquenos", "correct": false}, {"text": "alquinos", "correct": false}, {"text": "aromáticos", "correct": false}]}, {"type": "multichoice", "text": "Los compuestos formados solo por C y H se llaman…", "explain": "", "shuffle": true, "answers": [{"text": "hidrocarburos", "correct": true}, {"text": "aminas", "correct": false}, {"text": "alcoholes", "correct": false}, {"text": "amidas", "correct": false}]}]}}, {"id": 216, "part": 2, "chapter": 6, "title": "FUNCIONES ORGÁNICAS", "subtitle": "Ejercicio de emparejamiento", "instructions": "Desplegá las opciones de la derecha y elegí la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "a) El etanol del alcohol en gel", "correct": ["ALCOHOL"]}, {"left": "b) El ácido acético del vinagre", "correct": ["ÁCIDO"]}, {"left": "c) La acetona, quitaesmalte", "correct": ["CETONA"]}, {"left": "d) El aroma de la banana y la frutilla", "correct": ["ÉSTER"]}, {"left": "e) El metanal, formol", "correct": ["ALDEHÍDO"]}, {"left": "f) El éter etílico, anestesia", "correct": ["ÉTER"]}, {"left": "g) El metano del gas natural", "correct": ["HIDROCARBURO"]}], "options": ["ALCOHOL", "ÁCIDO", "CETONA", "ÉSTER", "ALDEHÍDO", "ÉTER", "HIDROCARBURO"]}}, {"id": 217, "part": 2, "chapter": 6, "title": "COMBUSTIÓN", "subtitle": "Indicá si las siguientes afirmaciones son VERDADERAS o FALSAS", "instructions": "Para cada frase seleccioná VERDADERO o FALSO.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "Con poca disponibilidad de oxígeno, la combustión produce carbón (C).", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Con una cantidad intermedia de oxígeno, la combustión produce monóxido de carbono (CO).", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "En la combustión completa se forman dióxido de carbono y agua.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Cuanto más completa es la combustión, menor es la cantidad de energía que se obtiene.", "explain": "Cuanto más completa, más energía.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "2 CH₄ + 4 O₂ → 2 CO₂ + 4 H₂O + energía representa una combustión incompleta.", "explain": "Con mucho oxígeno es completa.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "En las tres ecuaciones de combustión del metano de la guía, a partir de 2 CH₄ siempre se forman 4 H₂O.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El monóxido de carbono es un gas tóxico que inhibe la oxigenación de la sangre.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El humo negro de los escapes de los vehículos está formado por finas partículas de carbono.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El dióxido de carbono es uno de los principales gases de efecto invernadero.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}]}}, {"id": 218, "part": 2, "chapter": 6, "title": "SUSTANCIA CARBONADA DE LA COMBUSTIÓN", "subtitle": "Ejercicio de emparejamiento", "instructions": "Desplegá las opciones de la derecha y elegí la respuesta correcta.", "type": "match", "images": [], "data": {"items": [{"left": "a) Se forma cuando hay gran disponibilidad de oxígeno.", "correct": ["Dióxido de carbono (CO₂)"]}, {"left": "b) Se forma cuando hay poco oxígeno y queda un residuo negro sólido.", "correct": ["Carbón (C)"]}, {"left": "c) Es el gas tóxico que puede producir un brasero en un ambiente mal ventilado.", "correct": ["Monóxido de carbono (CO)"]}, {"left": "d) Son las partículas finas del humo negro de los escapes.", "correct": ["Carbón (C)"]}, {"left": "e) Es uno de los principales gases de efecto invernadero.", "correct": ["Dióxido de carbono (CO₂)"]}, {"left": "f) Se forma con una cantidad intermedia de oxígeno.", "correct": ["Monóxido de carbono (CO)"]}], "options": ["Dióxido de carbono (CO₂)", "Monóxido de carbono (CO)", "Carbón (C)"]}}, {"id": 219, "part": 2, "chapter": 6, "title": "BIOMOLÉCULAS", "subtitle": "Ejercicio de opción múltiple", "instructions": "Para cada frase seleccioná la única respuesta correcta.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "¿Qué biomolécula contiene C, H, O, N y P?", "explain": "Proteínas: C, H, O, N. Lípidos y glúcidos: C, H, O.", "shuffle": true, "answers": [{"text": "Los ácidos nucleicos", "correct": true}, {"text": "Las proteínas", "correct": false}, {"text": "Los lípidos", "correct": false}, {"text": "Los glúcidos", "correct": false}]}, {"type": "multichoice", "text": "¿Qué polisacárido forma la pared celular de los vegetales?", "explain": "Almidón: reserva vegetal. Glucógeno: reserva animal.", "shuffle": true, "answers": [{"text": "La celulosa", "correct": true}, {"text": "El almidón", "correct": false}, {"text": "El glucógeno", "correct": false}, {"text": "La glucosa", "correct": false}]}, {"type": "multichoice", "text": "¿Qué polisacárido usan las células animales como reserva de glucosa?", "explain": "", "shuffle": true, "answers": [{"text": "El glucógeno", "correct": true}, {"text": "El almidón", "correct": false}, {"text": "La celulosa", "correct": false}, {"text": "La sacarosa", "correct": false}]}, {"type": "multichoice", "text": "Los monómeros de las proteínas son los…", "explain": "", "shuffle": true, "answers": [{"text": "aminoácidos", "correct": true}, {"text": "nucleótidos", "correct": false}, {"text": "monosacáridos", "correct": false}, {"text": "triglicéridos", "correct": false}]}, {"type": "multichoice", "text": "Los monómeros de los ácidos nucleicos son los…", "explain": "", "shuffle": true, "answers": [{"text": "nucleótidos", "correct": true}, {"text": "aminoácidos", "correct": false}, {"text": "monosacáridos", "correct": false}, {"text": "ácidos grasos", "correct": false}]}, {"type": "multichoice", "text": "¿Cuáles son vitaminas liposolubles?", "explain": "Las hidrosolubles (B y C) se destruyen con la cocción.", "shuffle": true, "answers": [{"text": "A, D, E y K", "correct": true}, {"text": "El complejo B y la C", "correct": false}, {"text": "Solo la C", "correct": false}, {"text": "Solo las del complejo B", "correct": false}]}, {"type": "multichoice", "text": "La hemoglobina es una proteína que…", "explain": "", "shuffle": true, "answers": [{"text": "transporta oxígeno en los glóbulos rojos", "correct": true}, {"text": "controla el nivel de azúcar en sangre", "correct": false}, {"text": "forma las uñas y el pelo", "correct": false}, {"text": "acelera las reacciones químicas", "correct": false}]}, {"type": "multichoice", "text": "La insulina es una proteína con función…", "explain": "Controla el nivel de azúcar en sangre.", "shuffle": true, "answers": [{"text": "reguladora", "correct": true}, {"text": "estructural", "correct": false}, {"text": "de transporte", "correct": false}, {"text": "enzimática", "correct": false}]}, {"type": "multichoice", "text": "El colágeno, la queratina y la elastina son proteínas…", "explain": "", "shuffle": true, "answers": [{"text": "estructurales", "correct": true}, {"text": "enzimáticas", "correct": false}, {"text": "reguladoras", "correct": false}, {"text": "de transporte", "correct": false}]}, {"type": "multichoice", "text": "El azúcar que forma los nucleótidos del ARN es la…", "explain": "ADN: desoxirribosa. ARN: ribosa.", "shuffle": true, "answers": [{"text": "ribosa", "correct": true}, {"text": "desoxirribosa", "correct": false}, {"text": "glucosa", "correct": false}, {"text": "sacarosa", "correct": false}]}, {"type": "multichoice", "text": "En la doble hélice del ADN, la timina se aparea con la…", "explain": "A–T y C–G.", "shuffle": true, "answers": [{"text": "adenina", "correct": true}, {"text": "citosina", "correct": false}, {"text": "guanina", "correct": false}, {"text": "uracilo", "correct": false}]}]}}, {"id": 220, "part": 2, "chapter": 6, "title": "LÍPIDOS, GLÚCIDOS Y ÁCIDOS NUCLEICOS", "subtitle": "Indicar si las siguientes afirmaciones son verdaderas o falsas", "instructions": "Para cada frase seleccioná VERDADERO o FALSO.", "type": "quiz", "images": [], "data": {"questions": [{"type": "multichoice", "text": "Los lípidos no forman polímeros.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El colesterol interviene en la formación de la vitamina D.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Los triglicéridos son el material de reserva energética más común.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Los monosacáridos y los disacáridos se disuelven en agua.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "La celulosa es una reserva de energía de las plantas.", "explain": "Cumple función estructural; la reserva vegetal es el almidón.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "Los ácidos nucleicos son polímeros formados por nucleótidos.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "El ARN tiene dos cadenas enfrentadas que forman una doble hélice.", "explain": "Eso es el ADN; el ARN tiene una sola cadena.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "El ARN contiene uracilo en lugar de timina.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Las vitaminas hidrosolubles se acumulan en el tejido adiposo.", "explain": "Las que se acumulan son las liposolubles.", "answers": [{"text": "VERDADERO", "correct": false}, {"text": "FALSO", "correct": true}]}, {"type": "multichoice", "text": "Los aceites son triglicéridos líquidos a temperatura ambiente y las grasas son sólidas.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}, {"type": "multichoice", "text": "Las macrobiomoléculas pueden tener más de 100.000 átomos.", "explain": "", "answers": [{"text": "VERDADERO", "correct": true}, {"text": "FALSO", "correct": false}]}]}}, {"id": 221, "part": 2, "chapter": 6, "title": "BIOMOLÉCULAS", "subtitle": "Rellenar los espacios en blanco", "instructions": "Completá la palabra que falta. Las tildes y las mayúsculas no cuentan.", "type": "cloze", "images": [], "data": {"text": "1- Los hidratos de carbono contienen carbono, hidrógeno y {{1}}.\n\n2- El azúcar común o {{2}} es un disacárido formado por dos {{3}}.\n\n3- La reserva de glucosa de los vegetales es el {{4}} y la de los animales es el {{5}}.\n\n4- Las proteínas están formadas por unidades llamadas {{6}}; la proteína de los glóbulos rojos que transporta oxígeno es la {{7}}.\n\n5- Los monómeros de los ácidos nucleicos son los {{8}}: cada uno tiene un azúcar de cinco carbonos, una base nitrogenada y un grupo {{9}}.\n\n6- En el ADN el azúcar es la {{10}} y la base que se aparea con la guanina es la {{11}}.", "gaps": [{"n": 1, "answers": ["oxígeno"], "hint": ""}, {"n": 2, "answers": ["sacarosa"], "hint": ""}, {"n": 3, "answers": ["monosacáridos", "azúcares simples"], "hint": ""}, {"n": 4, "answers": ["almidón"], "hint": ""}, {"n": 5, "answers": ["glucógeno"], "hint": ""}, {"n": 6, "answers": ["aminoácidos"], "hint": ""}, {"n": 7, "answers": ["hemoglobina"], "hint": ""}, {"n": 8, "answers": ["nucleótidos"], "hint": ""}, {"n": 9, "answers": ["fosfato"], "hint": ""}, {"n": 10, "answers": ["desoxirribosa"], "hint": ""}, {"n": 11, "answers": ["citosina"], "hint": ""}], "caseSensitive": false}}];
